function init(){defaults({packing:[{id:'water',name:'带好水和随身用品',done:false},{id:'weather',name:'核对天气与开放信息',done:false}]})}init();
const votes=plan=>state.preferences.filter(x=>x.preference===plan.tag).reduce((n,x)=>n+(x.weight||1),0);
function planEditor(id){const t=state.plans.find(x=>x.id===id);editModal(t?'调整出游方案':'设计一个出游方案',field('这次出游叫什么','name','text',t?.name||'','required maxlength="60"')+select('主要主题','tag',['自然','文化','玩乐'],t?.tag)+field('全家预计花费 / 元','cost','number',t?.cost??200,'required min="0" max="100000" step="0.01"')+textfield('依次去哪里（每行一个地点）','route',t?.route.join('\n')||'',200),v=>{const route=v.route.split(/\n|→/).map(x=>x.trim()).filter(Boolean);if(!route.length){toast('至少添加一个地点');return false}if(t)Object.assign(t,{name:v.name,tag:v.tag,cost:+v.cost,route});else state.plans.push({id:uid(),name:v.name,tag:v.tag,cost:+v.cost,route});commit('方案已保存')});if(t){$('#edit-form').insertAdjacentHTML('beforeend',btn('移除这个候选方案','remove-plan','danger'));on('remove-plan',()=>{state.plans=state.plans.filter(x=>x.id!==id);if(state.selected===id)state.selected=null;closeModal();commit('方案已移除，可撤销')})}}
function render(){nav();const selected=state.plans.find(x=>x.id===state.selected);
if(active===0){$('#app').innerHTML=`<div class="two-col"><div>${hero('下一站，一起出发',`${state.plans.length}<small>个候选方案</small>`,'先听每个人的想法，再决定去哪里。','trip')}${heading('选一个大家期待的地方',btn('＋ 自己设计','add',''))}${list(state.plans,t=>`<article class="plan-card ${t.id===state.selected?'chosen':''}"><div class="between"><span class="pill">${esc(t.tag)} · ${votes(t)} 票偏好支持</span><button data-edit="${t.id}" aria-label="修改${esc(t.name)}">${icon('edit')}</button></div><h3>${esc(t.name)}</h3><p class="hint">${t.route.map(esc).join(' → ')}</p><div class="split-stat"><b>¥${t.cost}</b><span class="hint">全家预计总费用</span></div>${t.cost>state.budget?`<p class="warning notice">超出预算 ¥${(t.cost-state.budget).toFixed(2)}，先调整方案或商量预算。</p>`:''}<button class="${t.id===state.selected?'secondary':'primary'} full" data-select="${t.id}" ${t.cost>state.budget?'disabled':''}>${t.id===state.selected?'已选定 · 查看行程':'一起选择这个方案'}</button></article>`)}</div><aside class="stack"><section class="card"><div class="between"><h3>全家预算</h3>${btn('修改','budget-edit','')}</div><div class="big" style="font:36px Georgia;margin:14px 0">¥${state.budget}</div><p class="hint">示例价格用于练习，真实费用需出发前核对。</p></section><section class="card"><div class="between"><h3>每个人的小期待</h3>${btn('＋','pref-add','')}</div>${list(state.preferences,(x)=>`<div class="list-item"><div class="content"><strong>${esc(x.member)}</strong><p>喜欢 ${esc(x.preference)} · ${x.weight===2?'最想要 · 2 票':'一般喜欢 · 1 票'}</p></div><button data-pref="${state.preferences.indexOf(x)}" aria-label="修改${esc(x.member)}的偏好">${icon('edit')}</button></div>`)}</section></aside></div>`;on('add',()=>planEditor());actions('edit',planEditor);on('budget-edit',()=>editModal('商量一下预算',field('全家总预算 / 元','budget','number',state.budget,'required min="0" max="100000" step="0.01"'),v=>{state.budget=+v.budget;commit()}));function prefEditor(i){const old=state.preferences[i];editModal('听听你的想法',field('成员代号','member','text',old?.member||'','required maxlength="20" placeholder="例如：成员 C"')+select('最期待什么','preference',['自然','文化','玩乐'],old?.preference)+select('对你有多重要','importance',['一般喜欢 · 1 票','最想要 · 2 票'],old?.weight===2?'最想要 · 2 票':'一般喜欢 · 1 票'),v=>{const next={member:v.member,preference:v.preference,weight:v.importance.startsWith('最')?2:1};if(old)Object.assign(old,next);else state.preferences.push(next);commit()})}on('pref-add',()=>prefEditor());actions('pref',i=>prefEditor(+i));actions('select',id=>{state.selected=id;save();go(1)})}
if(active===1){$('#app').innerHTML=selected?`<div class="two-col"><div>${hero('我们的出游计划','一起去走走',esc(selected.name),'trip')}<section class="card" style="margin-top:20px"><h2>按这个顺序出发</h2><ol class="travel-route">${selected.route.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${btn('调整路线','route-edit','secondary full')}</section></div><aside class="card"><h3>${esc(selected.name)}</h3><div class="split-stat"><span>预计总费用</span><b>¥${selected.cost}</b></div><p class="notice ${selected.cost>state.budget?'warning':''}">${selected.cost>state.budget?'已超出当前预算，请重新商量。':`预算内还留有 ¥${(state.budget-selected.cost).toFixed(2)}`}</p><p class="hint" style="margin:16px 0">这是你们一起设计的顺序，不是实时地图或导航。</p>${btn('准备行李','packing','primary full')}</aside></div>`:`<div class="screen-body">${empty('还没有选定方案。先一起决定去哪里吧。')}${btn('去选方案','choose','primary full')}</div>`;on('choose',()=>go(0));on('route-edit',()=>planEditor(selected.id));on('packing',()=>go(2))}
if(active===2){$('#app').innerHTML=`<div class="screen-body">${heading('出发前，检查一下',btn('＋ 加一项','pack-add',''))}${progress(p.packing.filter(x=>x.done).length/Math.max(1,p.packing.length)*100)}<div class="list">${list(p.packing,x=>`<div class="list-item ${x.done?'complete':''}">${check('pack',x.id,x.done,(x.done?'撤销准备':'准备好')+x.name)}<div class="content"><strong>${esc(x.name)}</strong></div><button data-remove="${x.id}" aria-label="移除${esc(x.name)}">${icon('trash')}</button></div>`)}</div></div>`;actions('pack',id=>{const x=p.packing.find(x=>x.id===id);x.done=!x.done;commit()});actions('remove',id=>{p.packing=p.packing.filter(x=>x.id!==id);commit('已移除，可撤销')});on('pack-add',()=>editModal('还需要准备什么？',field('物品或准备事项','name','text','','required maxlength="60"'),v=>{p.packing.push({id:uid(),name:v.name,done:false});commit()}))}}
shell([['选方案','map'],['行程','flag'],['行李','list']]);render();
